public static int digitSum(int n) {
    int sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}

public static int firstHarshad(int start) {
    int n = start;
    while (n % digitSum(n) != 0) {
        n++;
    }
    return n;
}

public static int countWords(String s) {
    int count = 1;
    for (int i = 0; i < s.length(); i++) {
        if (s.substring(i, i + 1).equals(" ")) count++;
    }
    return count;
}

public static String longestWord(String s) {
    String best = "";
    String rest = s;
    while (rest.length() > 0) {
        int sp = rest.indexOf(" ");
        String word;
        if (sp == -1) { word = rest; rest = ""; }
        else { word = rest.substring(0, sp); rest = rest.substring(sp + 1); }
        if (word.length() > best.length()) best = word;
    }
    return best;
}

public class Battery {
    private int level;
    private int cycles;

    public Battery(int startLevel) {
        level = startLevel;
        cycles = 0;
    }

    public int use(int amount) {
        int used = Math.min(amount, level);
        level -= used;
        return used;
    }

    public void recharge() {
        level = 100;
        cycles++;
    }

    public int getLevel() { return level; }

    public int getCycles() { return cycles; }

    public boolean isLow() { return level < 20; }
}

public static double averagePositive(ArrayList<Integer> readings) {
    int sum = 0;
    int count = 0;
    for (Integer r : readings) {
        if (r > 0) {
            sum += r;
            count++;
        }
    }
    if (count == 0) {
        return 0.0;
    }
    return (double) sum / count;
}

public static void removeLaterDuplicates(ArrayList<String> names) {
    int i = 0;
    while (i < names.size()) {
        boolean dup = false;
        for (int j = 0; j < i; j++) {
            if (names.get(j).equals(names.get(i))) { dup = true; }
        }
        if (dup) { names.remove(i); }
        else { i++; }
    }
}

public static int[][] flipRows(int[][] grid) {
    int rows = grid.length;
    int cols = grid[0].length;
    int[][] result = new int[rows][cols];
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            result[r][c] = grid[r][cols - 1 - c];
        }
    }
    return result;
}

public static int[] columnMins(int[][] grid) {
    int[] mins = new int[grid[0].length];
    for (int c = 0; c < grid[0].length; c++) {
        int min = grid[0][c];
        for (int r = 1; r < grid.length; r++) {
            if (grid[r][c] < min) {
                min = grid[r][c];
            }
        }
        mins[c] = min;
    }
    return mins;
}
